window.USTAD_SOZLUK = (window.USTAD_SOZLUK || []).concat([
  { terim: "Alegori", anlam: "Bir düşünceyi ya da ahlak dersini, somut kişi ve olayların arkasına gizleyerek anlatan uzun ve öğretici anlatım biçimidir. Yüzeyde okunan hikâyenin altında sürekli bir mecaz katmanı bulunur.", ders: "Türkçe", konu: "Edebiyat Terimleri", ornek: "Fabllardaki hayvanlar aslında insan karakterlerini temsil eden bir alegoridir." },
  { terim: "Metafor", anlam: "Bir kavramı, benzetme unsurlarının hiçbirini kullanmadan doğrudan başka bir kavramın adıyla anlatma sanatıdır. Bir şeyi kendisi olmayan başka bir şey üzerinden düşünmemizi sağlar.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Öğretmenlik bir bahçıvanlıktır." },
  { terim: "Mecaz-ı mürsel", anlam: "Bir sözü, benzetme amacı gütmeden aralarındaki gerçek ilgi dolayısıyla başka bir söz yerine kullanmaktır. Parça-bütün, iç-dış, yer-insan gibi ilişkiler kurulur.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Bütün Ankara bu maçı konuşuyor." },
  { terim: "Kinaye", anlam: "Bir sözün hem gerçek hem mecaz anlamını birlikte taşıyacak biçimde kullanılıp asıl maksadın mecaz yönünde kastedilmesidir. Söylenenin tersi düşündürülerek ince bir iğneleme yapılır.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Bu kadar titiz çalışırsan bu iş hiç bitmez." },
  { terim: "Teşbih", anlam: "İki varlık ya da kavram arasında bir yönden benzerlik kurularak yapılan benzetmedir. Benzetmenin benzeyen, kendisine benzetilen, benzetme yönü ve benzetme edatı olmak üzere dört öğesi vardır.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Yanakları elma gibi kırmızıydı." },
  { terim: "İstiare", anlam: "Benzetmenin temel öğelerinden yalnızca birinin söylendiği benzetmedir. Benzeyen verilip kendisine benzetilen gizlenirse kapalı, bunun tersi yapılırsa açık istiare olur.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Bir hilâl uğruna ne güneşler batıyor." },
  { terim: "Tezat", anlam: "Birbirine karşıt anlamlı sözlerin ya da kavramların aynı cümlede bir arada kullanılmasıdır. Karşıtlık anlatıma derinlik ve etki katar.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Ağlarım aklıma geldikçe gülüştüklerimiz." },
  { terim: "Tekrir", anlam: "Bir sözün ya da dizenin anlamı güçlendirmek amacıyla tekrarlanmasıdır. Tekrar sayesinde dikkat yoğunlaşır ve duygu pekişir.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Vurulmuş, vurulmuş, vurulmuşum." },
  { terim: "Telmih", anlam: "Bir düşünce anlatılırken bilinen bir olaya, kişiye, esere ya da inanışa üstü kapalı biçimde gönderme yapılmasıdır. Göndermeyi sezen okur metnin anlam katmanına ortak olur.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Bu aşk bir Kerem ile Aslı hikâyesine benzedi." },
  { terim: "İrsal-i mesel", anlam: "Anlatılan düşünceyi desteklemek için söz arasında atasözü ya da özlü söz söylenmesidir. Yazar kendi cümlesini halk hafızasındaki bir yargıyla pekiştirir.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Ağaç yaş iken eğilir, demişler; eğitim küçük yaşta başlar." },
  { terim: "Seci", anlam: "Düz yazıda cümle sonlarında iç uyak sağlayacak biçimde aynı seslerin yinelenmesidir. Şiirdeki kafiyenin nesirdeki karşılığı sayılır.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "İlim ilim bilmektir, ilim kendin bilmektir." },
  { terim: "Cinas", anlam: "Yazılış ve söylenişleri aynı, anlamları ayrı olan sözcüklerin bir arada kullanılmasıdır. Ses benzerliği iki ayrı anlamı birden çağrıştırır.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Niçin kondun a bülbül, kapımdaki asmaya." },
  { terim: "Tenasüp", anlam: "Anlamca birbiriyle ilgili sözcüklerin aynı beyit ya da cümlede toplanmasıdır. Aralarındaki ilgi ifadeye uyum ve bütünlük kazandırır.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Gül, bülbül, bahar ve şafak aynı dizede buluştu." },
  { terim: "Hüsn-i talil", anlam: "Bir olayın gerçek nedenini bir yana bırakıp ona güzel ve hayal ürünü bir neden göstermektir. Şair, doğa olaylarını duygularla açıklar.", ders: "Türkçe", konu: "Söz Sanatları", ornek: "Gül, sevgilinin yüzünü görünce kızardı." },
  { terim: "Divan edebiyatı", anlam: "On üçüncü yüzyıldan on dokuzuncu yüzyıla kadar Osmanlı coğrafyasında Arap ve Fars edebiyatlarının etkisiyle gelişen yazılı edebiyat geleneğidir. Aruz ölçüsü, mazmun sistemi ve ağır dil onun belirgin özellikleridir.", ders: "Türkçe", konu: "Edebi Akımlar", ornek: "Fuzûlînin gazelleri divan edebiyatının doruk örneklerindendir." },
  { terim: "Tanzimat edebiyatı", anlam: "1860 sonrasında Batı edebiyatının etkisiyle gelişen ve toplumsal sorunlara yönelen edebiyat dönemidir. Roman, tiyatro ve gazete bu dönemde edebiyatımıza girmiştir.", ders: "Türkçe", konu: "Edebi Akımlar", ornek: "Şinasi şiirleriyle Tanzimat edebiyatının öncülüğünü yaptı." },
  { terim: "Servet-i Fünun", anlam: "1896-1901 arasında Servet-i Fünun dergisi çevresinde toplanan topluluğun oluşturduğu edebiyat dönemidir. Sanat sanat içindir anlayışı, bireysel konular ve ağır dil öne çıkar.", ders: "Türkçe", konu: "Edebi Akımlar", ornek: "Tevfik Fikret bu dönemin en güçlü şairi sayılır." },
  { terim: "Garip akımı", anlam: "1940lı yıllarda Orhan Veli ve arkadaşlarının başlattığı, şiiri ölçü ve uyak gibi kalıplardan kurtarmayı amaçlayan harekettir. Günlük yaşam ve halk dili şiire girmiştir.", ders: "Türkçe", konu: "Edebi Akımlar", ornek: "Kitabın adı Garip olduğu için akım da o adla anıldı." },
  { terim: "Gazel", anlam: "Divan şiirinde beş ile on beş beyit arasında yazılan, aşk ve güzellik konularını işleyen nazım biçimidir. İlk beyit kendi arasında, sonraki beyitlerin ikinci dizeleri ilk beyitle kafiyelenir.", ders: "Türkçe", konu: "Divan Şiiri Nazım Biçimleri", ornek: "Baharın gelişi gazellerde sevgilinin gelişiyle anlatılır." },
  { terim: "Kaside", anlam: "Divan şiirinde genellikle bir devlet büyüğünü övmek amacıyla yazılan uzun nazım biçimidir. Beyit sayısı çoğunlukla otuz üç ile doksan dokuz arasında değişir.", ders: "Türkçe", konu: "Divan Şiiri Nazım Biçimleri", ornek: "Şairin kasidesi padişahın huzurunda okundu." },
  { terim: "Mesnevi", anlam: "Divan edebiyatında her beyti kendi arasında kafiyelenen ve konu sınırı bulunmayan nazım biçimidir. Uzun aşk ve macera hikâyeleri bu biçimle yazılmıştır.", ders: "Türkçe", konu: "Divan Şiiri Nazım Biçimleri", ornek: "Mevlânânın Mesnevisi öğretici hikâyelerle doludur." },
  { terim: "Koşma", anlam: "Âşık edebiyatında dörtlüklerle söylenen ve hece ölçüsünün on birli kalıbıyla yazılan lirik nazım biçimidir. Son dörtlükte şairin mahlası yer alır.", ders: "Türkçe", konu: "Halk Şiiri Nazım Biçimleri", ornek: "Sazı eline alıp bir koşma söyledi." },
  { terim: "Semai", anlam: "Âşık edebiyatında sekizli hece ölçüsüyle ve dörtlüklerle söylenen nazım biçimidir. Konusu genellikle doğa, aşk ve güzelliktir.", ders: "Türkçe", konu: "Halk Şiiri Nazım Biçimleri", ornek: "Dağların güzelliğini anlatan semai dillerde dolaşıyordu." },
  { terim: "Taşlama", anlam: "Halk şiirinde toplumun ya da kişilerin kusurlarını eleştiren, iğneleyici bir dille söylenen nazım biçimidir.", ders: "Türkçe", konu: "Halk Şiiri Nazım Biçimleri", ornek: "Şair taşlamasında görevini kötüye kullananları eleştirdi." },
  { terim: "Ağıt", anlam: "Ölen bir kişinin ardından duyulan acıyı ve onun iyi niteliklerini anlatan ezgili söyleyiştir. Anadolu'da genellikle kadınlar tarafından kendine özgü bir ezgiyle söylenir.", ders: "Türkçe", konu: "Metin Türleri", ornek: "Annesinin ardından bir ağıt yaktı." },
  { terim: "Destan", anlam: "Bir milletin kahramanlıklarını, savaşlarını ve ortak acılarını olağanüstü öğelerle anlatan uzun anlatıdır. Toplumun hafızasını kuşaktan kuşağa taşır.", ders: "Türkçe", konu: "Metin Türleri", ornek: "Oğuz Kağan Destanı Türk destan geleneğinin ilk büyük örneğidir." },
  { terim: "Fabl", anlam: "Kişilerinin çoğunlukla hayvanlar olduğu, sonunda bir ahlak dersi verilen kısa ve genellikle manzum anlatıdır. Kahramanlar insan gibi konuşur ve davranır.", ders: "Türkçe", konu: "Metin Türleri", ornek: "Karınca ile ağustos böceğinin hikâyesi bir fabldır." },
  { terim: "Halk hikâyesi", anlam: "Âşıklar tarafından saz eşliğinde anlatılan, gerçek ile olağanüstülüğün iç içe geçtiği uzun anlatı türüdür. Aşk ve kahramanlık konuları öne çıkar.", ders: "Türkçe", konu: "Metin Türleri", ornek: "Kerem ile Aslı bir halk hikâyesidir." },
  { terim: "Portre", anlam: "Bir kişinin dış görünüşünü, davranışlarını ve karakter özelliklerini ayrıntılı biçimde tanıtan yazıdır. Fiziksel ve ruhsal özellikler birlikte verilebilir.", ders: "Türkçe", konu: "Metin Türleri", ornek: "Roman, kahramanın portresini ilk bölümde çiziyor." },
  { terim: "Mülakat", anlam: "Bir konuda uzman ya da yetkili bir kişiyle bilgi almak amacıyla yapılan görüşmenin yazıya geçirilmiş biçimidir. Sorular önceden hazırlanır, cevaplar değiştirilmeden aktarılır.", ders: "Türkçe", konu: "Metin Türleri", ornek: "Gazeteci mülakatı hiç değiştirmeden yayımladı." },
  { terim: "Ünlü düşmesi", anlam: "İki heceli bazı sözcüklere ünlüyle başlayan bir ek geldiğinde ikinci hecedeki ünlünün düşmesidir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Ağız sözcüğü ek alınca ağzım biçiminde yazılır." },
  { terim: "Ünsüz benzeşmesi", anlam: "Sert ünsüzle biten bir sözcüğe yumuşak ünsüzle başlayan bir ek geldiğinde ekin sertleşerek söylenmesi ve yazılmasıdır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Kitap sözcüğüne -cı eki gelince kitapçı olur." },
  { terim: "Ünsüz yumuşaması", anlam: "Sert ünsüzlerden p, ç, t, k ile biten sözcükler ünlüyle başlayan ek aldığında bu ünsüzlerin b, c, d, g, ğ seslerine dönüşmesidir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Ağaç sözcüğü ek alınca ağacı biçimini alır." },
  { terim: "Kaynaştırma harfi", anlam: "Ünlüyle biten bir sözcüğe ünlüyle başlayan bir ek getirildiğinde araya giren y, ş, s ve n sesleridir. Bu sesler iki ünlünün yan yana gelmesini engeller.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "İki sözcüğüne ek gelince ikişer biçiminde yazılır." },
  { terim: "Ulama", anlam: "Ünsüzle biten bir sözcüğün ardından ünlüyle başlayan bir sözcük geldiğinde iki sözcüğün hecelerin birleşmesiyle okunmasıdır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Ağaç altında uzun süre oturduk." },
  { terim: "Vurgu", anlam: "Bir hecenin diğerlerine göre daha baskılı ve daha uzun söylenmesidir. Türkçede sözcük vurgusu genellikle son hecede bulunur.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Kalem sözcüğünde vurgu ikinci hecededir." },
  { terim: "Kök", anlam: "Bir sözcüğün anlamlı en küçük parçasıdır ve kendisinden yapım ekiyle yeni sözcükler türetilebilir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Göz sözcüğü gözlük sözcüğünün köküdür." },
  { terim: "Yapım eki", anlam: "Eklendiği sözcükten yeni ve farklı anlamda bir sözcük türeten ektir. Sözcüğün anlamını ve türünü değiştirebilir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Bilgi sözcüğü bil kökünden yapım ekiyle türemiştir." },
  { terim: "Çekim eki", anlam: "Sözcüğün anlamını değiştirmeden onun cümle içindeki görevini belirleyen ektir. İsim ve fiil çekim ekleri olmak üzere ikiye ayrılır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Evde sözcüğündeki -de eki çekim ekidir." },
  { terim: "Fiilimsi", anlam: "Fiilden türediği hâlde cümlede isim, sıfat ya da zarf gibi görev yapan sözcüklerdir. İsim-fiil, sıfat-fiil ve zarf-fiil olmak üzere üçe ayrılır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Okumak onun en büyük tutkusuydu." },
  { terim: "İsim-fiil", anlam: "Fiillere -mek, -mak, -me, -ma, -iş ve -ış ekleri getirilerek yapılan, cümlede isim görevinde kullanılan fiilimsidir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Yüzmek bütün kasları çalıştırır." },
  { terim: "Sıfat-fiil", anlam: "Fiillere -an, -ası, -mez, -ar, -dik, -ecek ve -miş ekleri getirilerek yapılan, kendisinden sonra gelen ismi niteleyen fiilimsidir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Koşan çocuk bir anda yere düştü." },
  { terim: "Zarf-fiil", anlam: "Fiillere -ken, -alı, -madan, -ince, -ip, -erek, -dikçe ve -meksizin ekleri getirilerek yapılan, cümlede zarf görevinde kullanılan fiilimsidir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Gülerek içeri girdi." },
  { terim: "Tamlama", anlam: "İki ya da daha fazla sözcüğün aralarında anlam bağı kurarak oluşturduğu söz öbeğidir. İsim, sıfat ve zincirleme tamlama gibi türleri vardır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Okulun bahçesi bir isim tamlamasıdır." },
  { terim: "Belirtili nesne", anlam: "Yüklemin bildirdiği işten belirli biçimde etkilenen ve belirtme durumu eki almış nesnedir. Yükleme neyi ve kimi soruları sorularak bulunur.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Kitabı masaya bıraktı." },
  { terim: "Dolaylı tümleç", anlam: "Yüklemin anlamını yer, yön ve bulunma bakımından tamamlayan ve -e, -de, -den eklerini alan öğedir. Yükleme nereye, nerede ve nereden soruları sorularak bulunur.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Öğrenciler okula gitti." },
  { terim: "Zarf tümleci", anlam: "Yüklemin anlamını zaman, durum, miktar, sebep ve koşul bakımından tamamlayan öğedir. Yükleme nasıl, ne zaman ve niçin soruları sorularak bulunur.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Sabah çok erken kalktı." },
  { terim: "Edat", anlam: "Tek başına anlamı bulunmayan, ancak başka sözcüklerle birlikte kullanıldığında anlam kazanan sözcük türüdür.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Senin için her şeyi yaparım." },
  { terim: "Bağlaç", anlam: "Sözcükleri, söz öbeklerini ya da cümleleri birbirine bağlayan ve aralarında anlam ilgisi kuran sözcük türüdür.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Hem çalıştı hem okudu." },
  { terim: "Zamir", anlam: "İsmin yerini geçici olarak tutan ve ismin alabildiği ekleri alabilen sözcük türüdür. Kişi, işaret, belgisiz ve soru zamiri gibi çeşitleri vardır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Onu dün akşam çarşıda gördüm." },
  { terim: "Basit cümle", anlam: "Tek bir yargı bildiren, içinde fiilimsi ya da ikinci bir yüklem bulunmayan cümledir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Hava bugün çok güzel." },
  { terim: "Birleşik cümle", anlam: "İçinde birden fazla yargı bulunan cümledir. Girişik, şartlı, ki'li ve iç içe birleşik cümle olmak üzere çeşitleri vardır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Gelirse hep birlikte gideriz." },
  { terim: "Sıralı cümle", anlam: "Anlamca birbirine bağlı olan, virgül ya da noktalı virgülle art arda dizilen ve her biri kendi yüklemini taşıyan cümlelerden oluşan cümle topluluğudur.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Geldi, oturdu, hiç konuşmadı." },
  { terim: "Bağlı cümle", anlam: "Aralarında anlam ilgisi bulunan cümlelerin bir bağlaçla birbirine bağlanmasıyla oluşan cümledir.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Bize geldi ama hiçbir şey söylemedi." },
  { terim: "Edilgen çatı", anlam: "Yüklemin gösterdiği işi yapanın belli olmadığı, öznenin işi yapmayıp işten etkilendiği fiil çatısıdır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Kitap dün akşam okundu." },
  { terim: "Ettirgen çatı", anlam: "Bir işin başkasına yaptırıldığı anlamını taşıyan fiil çatısıdır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Çocuğa odasını toplattı." },
  { terim: "Dönüşlü çatı", anlam: "İşi yapan ile işten etkilenenin aynı kişi olduğu fiil çatısıdır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "Küçük kız aynanın önünde tarandı." },
  { terim: "İşteş çatı", anlam: "İşin birlikte ya da karşılıklı olarak yapıldığını bildiren fiil çatısıdır.", ders: "Türkçe", konu: "Dil Bilgisi", ornek: "İki arkadaş yolda karşılaştı." },
  { terim: "Nesnel anlatım", anlam: "Anlatılanların kişisel yorum katılmadan ve kanıtlanabilir biçimde aktarıldığı anlatımdır. Duygu ve beğeni bildiren ifadelere yer verilmez.", ders: "Türkçe", konu: "Anlatım Biçimleri", ornek: "Türkiye 81 ilden oluşur." },
  { terim: "Öznel anlatım", anlam: "Anlatılanların kişisel görüş, duygu ve beğeniyle aktarıldığı anlatımdır. Söylenenlerin kanıtlanması mümkün değildir.", ders: "Türkçe", konu: "Anlatım Biçimleri", ornek: "Bu, okuduğum en güzel şiirdir." },
  { terim: "Asal sayı", anlam: "Yalnızca bir ve kendisine tam bölünebilen, birden büyük doğal sayıdır. En küçük asal sayı ikidir.", ders: "Matematik", konu: "Sayılar", ornek: "İki, üç ve beş birer asal sayıdır." },
  { terim: "Aralarında asal", anlam: "Birden başka ortak böleni bulunmayan iki ya da daha fazla tam sayı için kullanılan ifadedir. Sayıların kendileri asal olmak zorunda değildir.", ders: "Matematik", konu: "Sayılar", ornek: "Sekiz ile dokuz aralarında asaldır." },
  { terim: "Faktöriyel", anlam: "Birden o sayıya kadar bütün doğal sayıların çarpımıdır ve n! biçiminde gösterilir. Sıfır faktöriyel bire eşit kabul edilir.", ders: "Matematik", konu: "Sayılar", ornek: "Beş faktöriyel yüz yirmiye eşittir." },
  { terim: "Basamak değeri", anlam: "Bir rakamın bulunduğu basamağa göre aldığı değerdir. Rakamın sayı değeri ile basamağın büyüklüğünün çarpımıyla bulunur.", ders: "Matematik", konu: "Sayılar", ornek: "456 sayısında altının basamak değeri altmıştır." },
  { terim: "Rasyonel sayı", anlam: "Biri sıfırdan farklı iki tam sayının bölümü biçiminde yazılabilen sayıdır. Ondalık gösterimi ya sonludur ya da devirlidir.", ders: "Matematik", konu: "Sayılar", ornek: "Üç bölü dört bir rasyonel sayıdır." },
  { terim: "İrrasyonel sayı", anlam: "İki tam sayının bölümü biçiminde yazılamayan gerçek sayıdır. Ondalık açılımı sonsuzdur ve düzenli bir devir göstermez.", ders: "Matematik", konu: "Sayılar", ornek: "Karekök iki bir irrasyonel sayıdır." },
  { terim: "Mutlak değer", anlam: "Bir sayının sayı doğrusunda sıfıra olan uzaklığıdır ve her zaman sıfır ya da pozitiftir.", ders: "Matematik", konu: "Sayılar", ornek: "Eksi yedinin mutlak değeri yedidir." },
  { terim: "Üslü sayı", anlam: "Bir sayının kendisiyle belirli sayıda tekrarlı çarpımını gösteren yazım biçimidir. Sıfırdan farklı bir sayının sıfırıncı kuvveti birdir.", ders: "Matematik", konu: "Sayılar", ornek: "İkinin beşinci kuvveti otuz iki eder." },
  { terim: "Karekök", anlam: "Karesi verilen sayıya eşit olan negatif olmayan sayıdır. Geometride kenar uzunluğu ile alan arasındaki bağıntıyı kurar.", ders: "Matematik", konu: "Sayılar", ornek: "Yirmi beşin karekökü beştir." },
  { terim: "EBOB", anlam: "Birden fazla tam sayının ortak bölenlerinin en büyüğüdür. Sayılar aralarında asal ise birbirine eşit çıkar.", ders: "Matematik", konu: "Sayılar", ornek: "On iki ile on sekizin EBOB'u altıdır." },
  { terim: "EKOK", anlam: "Birden fazla tam sayının ortak katlarının en küçüğüdür. İki sayının çarpımı, EBOB ile EKOK çarpımına eşittir.", ders: "Matematik", konu: "Sayılar", ornek: "Dört ile altının EKOK'u on ikidir." },
  { terim: "Oran", anlam: "Aynı birimle ölçülen iki çokluğun birbirine bölünerek karşılaştırılmasıdır. Sonuç birimsiz bir sayıdır.", ders: "Matematik", konu: "Oran-Orantı", ornek: "Sınıftaki kızların erkeklere oranı üç bölü beştir." },
  { terim: "Doğru orantı", anlam: "İki çokluktan biri artarken diğeri de aynı oranda artan, biri azalırken diğeri de azalan ilişkidir. Bölümleri sabittir.", ders: "Matematik", konu: "Oran-Orantı", ornek: "Aynı hızla giden araçta yol ile yakıt doğru orantılıdır." },
  { terim: "Ters orantı", anlam: "İki çokluktan biri artarken diğerinin aynı oranda azaldığı ilişkidir. Çarpımları sabittir.", ders: "Matematik", konu: "Oran-Orantı", ornek: "İşçi sayısı artınca işin bitme süresi ters orantılı olarak azalır." },
  { terim: "Yüzde", anlam: "Bir çokluğun yüz eşit parçasından kaçını ifade ettiğini gösteren orandır. Paydası yüz olan kesir olarak yazılır.", ders: "Matematik", konu: "Oran-Orantı", ornek: "Yüzde yirmi zam, yüz liralık ürüne yirmi lira ekler." },
  { terim: "Cebirsel ifade", anlam: "İçinde en az bir değişken ve işlem bulunan ifadedir. Değişkenlere sayı değeri verilerek ifadenin değeri hesaplanır.", ders: "Matematik", konu: "Cebir", ornek: "Üç x artı iki bir cebirsel ifadedir." },
  { terim: "Özdeşlik", anlam: "İçindeki değişkenlerin alabileceği bütün değerler için doğru olan eşitliktir. Denklemden farkı, çözüm kümesinin bütün gerçek sayılar olmasıdır.", ders: "Matematik", konu: "Cebir", ornek: "İki terimin toplamının karesi bir özdeşliktir." },
  { terim: "Denklem", anlam: "İçinde değişken bulunan ve yalnızca bazı değerler için doğru olan eşitliktir. Eşitliği sağlayan değere denklemin kökü denir.", ders: "Matematik", konu: "Cebir", ornek: "Üç x eksi altı eşittir sıfır denkleminin kökü ikidir." },
  { terim: "Eşitsizlik", anlam: "İki cebirsel ifadenin büyük, küçük, büyük eşit ya da küçük eşit simgeleriyle karşılaştırılmasıdır. Çözüm kümesi genellikle bir aralıktır.", ders: "Matematik", konu: "Cebir", ornek: "İki x büyüktür sekiz eşitsizliğinin çözümü x büyüktür dörttür." },
  { terim: "Polinom", anlam: "Bir değişkenin doğal sayı kuvvetlerinin katsayılarla çarpımının toplamı biçiminde yazılan ifadedir. En büyük kuvvete polinomun derecesi denir.", ders: "Matematik", konu: "Cebir", ornek: "Üç x kare artı iki x eksi bir bir polinomdur." },
  { terim: "Çarpanlara ayırma", anlam: "Bir ifadenin, çarpım durumundaki daha basit ifadelerin çarpımı biçiminde yazılmasıdır. Ortak çarpan parantezine alma ve özdeşliklerden yararlanılır.", ders: "Matematik", konu: "Cebir", ornek: "İki x kare eksi sekiz, iki çarpı x kare eksi dört biçiminde yazılır." },
  { terim: "Fonksiyon", anlam: "Bir kümenin her elemanını başka bir kümenin yalnızca bir elemanına eşleyen kuraldır. Tanım kümesindeki her elemanın mutlaka bir görüntüsü olmalıdır.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "Her sayıya karesini eşleyen kural bir fonksiyondur." },
  { terim: "Tanım kümesi", anlam: "Bir fonksiyonda değer verilebilecek bütün girdilerin oluşturduğu kümedir. Paydanın sıfır olduğu ve kökün negatif olduğu değerler dışarıda kalır.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "Karekök fonksiyonunun tanım kümesi negatif olmayan sayılardır." },
  { terim: "Görüntü kümesi", anlam: "Tanım kümesindeki elemanların fonksiyon kuralına göre eşlendiği bütün değerlerin kümesidir.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "Fonksiyonun görüntü kümesi sıfır ile yedi arasındadır." },
  { terim: "Bire bir fonksiyon", anlam: "Tanım kümesindeki farklı elemanları görüntü kümesindeki farklı elemanlara eşleyen fonksiyondur. Yatay doğru testiyle anlaşılır.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "Her girdi farklı bir çıktı üretiyorsa fonksiyon bire birdir." },
  { terim: "Örten fonksiyon", anlam: "Görüntü kümesindeki her elemanın en az bir girdinin görüntüsü olduğu fonksiyondur. Tanım kümesi değer kümesine tam olarak oturur.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "Değer kümesi sonuç kümesine eşitse fonksiyon örtendir." },
  { terim: "Bileşke fonksiyon", anlam: "Bir fonksiyonun çıktısının ikinci bir fonksiyona girdi olarak verilmesiyle elde edilen fonksiyondur. Genel olarak değişme özelliği yoktur.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "Önce karesini alıp sonra iki ekleyen kural bir bileşke fonksiyondur." },
  { terim: "Ters fonksiyon", anlam: "Bire bir ve örten bir fonksiyonun eşlemesini tersine çeviren fonksiyondur. Grafiği, asıl fonksiyonun grafiğinin y eşittir x doğrusuna göre simetriğidir.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "İki ekleyen fonksiyonun tersi iki çıkarır." },
  { terim: "Logaritma", anlam: "Bir sayının belirli bir tabana göre hangi kuvvet olduğunu bulma işlemidir. Üs almanın tersi işlemdir.", ders: "Matematik", konu: "Fonksiyonlar", ornek: "İkinin tabanına göre sekizin logaritması üçtür." },
  { terim: "Permütasyon", anlam: "Bir kümenin elemanlarının sıralamasının önemli olduğu seçme ve dizme işlemidir. Yer değiştirmek sonucu değiştirir.", ders: "Matematik", konu: "Sayma", ornek: "Beş kişiden ikisinin sıralı seçimi yirmi farklı biçimde olur." },
  { terim: "Kombinasyon", anlam: "Bir kümeden sıralama önemsenmeden yapılan seçme işlemidir. Grup içindeki yer değişikliği yeni bir seçim sayılmaz.", ders: "Matematik", konu: "Sayma", ornek: "Beş kişiden ikisinin seçimi on farklı biçimde olur." },
  { terim: "Olasılık", anlam: "Bir olayın gerçekleşme şansının matematiksel ölçüsüdür. İstenen durumların sayısının tüm durumların sayısına bölümüyle bulunur ve sıfır ile bir arasında değer alır.", ders: "Matematik", konu: "Olasılık", ornek: "Zarın altı gelme olasılığı altıda birdir." },
  { terim: "Küme", anlam: "İyi tanımlanmış nesnelerin oluşturduğu topluluktur. Aynı nesne bir kümede yalnızca bir kez yer alır.", ders: "Matematik", konu: "Kümeler", ornek: "Sınıftaki bütün öğrenciler bir küme oluşturur." },
  { terim: "Alt küme", anlam: "Bir kümenin bütün elemanlarının başka bir kümede de bulunması durumudur. Boş küme her kümenin alt kümesidir.", ders: "Matematik", konu: "Kümeler", ornek: "İki ve üç elemanlı kümelerden küçük olanı büyüğünün alt kümesidir." },
  { terim: "Kesişim", anlam: "İki kümenin ortak elemanlarından oluşan kümedir. Ortak eleman yoksa kesişim boş kümedir.", ders: "Matematik", konu: "Kümeler", ornek: "İki kümenin ortak elemanları kesişimi verir." },
  { terim: "Birleşim", anlam: "İki kümenin bütün elemanlarının tekrarsız olarak bir araya getirilmesiyle oluşan kümedir.", ders: "Matematik", konu: "Kümeler", ornek: "Her iki kümenin elemanları birleşimde birer kez yer alır." },
  { terim: "Aritmetik dizi", anlam: "Ardışık terimleri arasındaki farkın sabit olduğu sayı dizisidir. Bu sabit farka ortak fark denir.", ders: "Matematik", konu: "Diziler", ornek: "Üç, yedi, on bir, on beş bir aritmetik dizidir." },
  { terim: "Geometrik dizi", anlam: "Ardışık terimleri arasındaki oranın sabit olduğu sayı dizisidir. Bu sabite ortak çarpan denir.", ders: "Matematik", konu: "Diziler", ornek: "İki, altı, on sekiz bir geometrik dizidir." },
  { terim: "Dar açı", anlam: "Ölçüsü sıfır ile doksan derece arasında bulunan açıdır.", ders: "Matematik", konu: "Geometri", ornek: "Otuz derecelik açı bir dar açıdır." },
  { terim: "Dik açı", anlam: "Ölçüsü tam doksan derece olan açıdır. Kolları birbirine diktir.", ders: "Matematik", konu: "Geometri", ornek: "Karenin bütün iç açıları dik açıdır." },
  { terim: "Geniş açı", anlam: "Ölçüsü doksan ile yüz seksen derece arasında bulunan açıdır.", ders: "Matematik", konu: "Geometri", ornek: "Yüz otuz derecelik açı bir geniş açıdır." },
  { terim: "Tümler açı", anlam: "Ölçüleri toplamı doksan derece olan iki açıdan her biridir.", ders: "Matematik", konu: "Geometri", ornek: "Altmış derecenin tümleyeni otuz derecedir." },
  { terim: "Bütünler açı", anlam: "Ölçüleri toplamı yüz seksen derece olan iki açıdan her biridir.", ders: "Matematik", konu: "Geometri", ornek: "Yüz yirmi derecenin bütünleyeni altmış derecedir." },
  { terim: "Açıortay", anlam: "Bir açıyı iki eşit parçaya bölen ışındır. Üçgende açıortaylar iç teğet çemberinin merkezinde kesişir.", ders: "Matematik", konu: "Geometri", ornek: "Açıortay, açının kollarına eşit uzaklıktadır." },
  { terim: "Yarıçap", anlam: "Çemberin merkezini çember üzerindeki herhangi bir noktaya birleştiren doğru parçasıdır. Uzunluğu çapın yarısıdır.", ders: "Matematik", konu: "Geometri", ornek: "Yarıçapı yedi santimetre olan çemberin çapı on dört olur." },
  { terim: "Kiriş", anlam: "Çember üzerindeki iki noktayı birleştiren doğru parçasıdır. Merkezden geçen en uzun kiriş çaptır.", ders: "Matematik", konu: "Geometri", ornek: "Çemberdeki en uzun kiriş çaptır." },
  { terim: "Teğet", anlam: "Bir eğriye ya da çembere yalnızca bir noktada değen doğrudur. Çemberde teğet, değme noktasındaki yarıçapa diktir.", ders: "Matematik", konu: "Geometri", ornek: "Teğet doğrusu çemberi tek noktada keser." },
  { terim: "Eşlik", anlam: "Karşılıklı kenar ve açıları eşit olan şekiller arasındaki ilişkidir. Eş şekillerin alanları da eşittir.", ders: "Matematik", konu: "Geometri", ornek: "İki eş üçgenin bütün kenarları aynıdır." },
  { terim: "Benzerlik", anlam: "Karşılıklı açıları eşit, karşılıklı kenarları orantılı olan şekiller arasındaki ilişkidir. Benzer şekillerin alanları oranın karesiyle orantılıdır.", ders: "Matematik", konu: "Geometri", ornek: "İki benzer üçgenin kenarları aynı oranda büyür." },
  { terim: "Pisagor bağıntısı", anlam: "Dik üçgende dik kenarların kareleri toplamının hipotenüsün karesine eşit olduğunu bildiren bağıntıdır.", ders: "Matematik", konu: "Geometri", ornek: "Dik kenarları üç ve dört olan üçgende hipotenüs beştir." },
  { terim: "Kut anlayışı", anlam: "Türklerde yönetme yetkisinin Tanrı tarafından hükümdara verildiğine inanılan kutsal güçtür. Bu yetki kan yoluyla hanedan üyelerine geçtiği için taht kavgaları sık görülmüştür.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Kağan, kut aldığına inandığı için buyruklarını Tanrı adına verirdi." },
  { terim: "Kurultay", anlam: "İslamiyet öncesi Türk devletlerinde devlet işlerinin görüşüldüğü danışma meclisidir. Kağanın başkanlık ettiği kurultayda savaş, barış ve antlaşma kararları alınırdı.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Kağan kurultayı toplayarak savaş kararını danıştı." },
  { terim: "İkili teşkilat", anlam: "Devletin doğu ve batı olmak üzere iki kanada ayrılarak yönetilmesi uygulamasıdır. Doğu kanadı kağanın, batı kanadı genellikle yabgunun yönetimindeydi.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Asya Hun Devleti ikili teşkilatla yönetilmiştir." },
  { terim: "Tümen", anlam: "İslamiyet öncesi Türk ordusunda on bin askerden oluşan en büyük birliktir. Ordu onluk sisteme göre düzenlenmiştir.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "On bin atlı askere bir tümen denirdi." },
  { terim: "Şölen", anlam: "İslamiyet öncesi Türklerde zafer, düğün ve dini törenler nedeniyle verilen büyük ziyafettir. Toplumsal dayanışmayı güçlendirirdi.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Zaferden sonra bütün boylar şölende bir araya geldi." },
  { terim: "Yuğ", anlam: "İslamiyet öncesi Türklerde ölü gömme törenine verilen addır. Ölünün ardından at kurban edilir ve mezarına balbal dikilirdi.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Hakanın ölümü üzerine büyük bir yuğ töreni düzenlendi." },
  { terim: "Otağ", anlam: "Hükümdar ve devlet ileri gelenlerinin kullandığı büyük ve süslü çadırdır. Otağın kurulduğu yere göre hükümdarın otoritesi simgelenirdi.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Kağanın otağı ordugâhın ortasına kuruldu." },
  { terim: "Balbal", anlam: "Ölen kişinin mezarı başına dikilen ve onun öldürdüğü düşman sayısını gösteren taş heykeldir. Savaşçılık gücünü simgelerdi.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Mezarın çevresine sayısız balbal dikilmişti." },
  { terim: "Onlu sistem", anlam: "Ordunun en küçük birlikten tümene kadar onluk, yüzlük ve binlik basamaklara ayrıldığı teşkilatlanma düzenidir. Türk orduları bu düzeni uzun süre korumuştur.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Türk ordusu onlu sistem sayesinde kolayca yönetilebiliyordu." },
  { terim: "Orhun Yazıtları", anlam: "İkinci Göktürk Devleti döneminde Bilge Kağan, Kültigin ve Tonyukuk adına dikilen, Türkçenin bilinen ilk uzun metinleridir. Türk devlet anlayışı ve tarihi hakkında bilgi verir.", ders: "Tarih", konu: "İslamiyet Öncesi Türk Tarihi", ornek: "Orhun Yazıtları Türk dilinin ilk yazılı belgeleri sayılır." },
  { terim: "İkta sistemi", anlam: "Devlete ait toprakların hizmet karşılığında görevlilere tahsis edildiği toprak yönetim düzenidir. Toprağı işleyen çiftçi üretimden, sahibi ise asker beslemekten sorumluydu.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "İkta sistemi hem üretimi hem asker beslenmesini düzenliyordu." },
  { terim: "Nizamiye Medresesi", anlam: "Büyük Selçuklu Devleti zamanında Nizamülmülk tarafından kurulan yükseköğretim kurumlarıdır. Devlet memuru ve din bilgini yetiştirmeyi amaçlamıştır.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Nizamiye Medreseleri dönemin en gelişmiş eğitim kurumlarıydı." },
  { terim: "Atabey", anlam: "Selçuklularda şehzadeleri yetiştirmekle görevlendirilen deneyimli devlet adamıdır. Şehzade tahta çıktığında eyaletlerde zaman zaman bağımsız hareket edebilmiştir.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Atabey, şehzadeye devlet yönetimini öğretti." },
  { terim: "Divan-ı Saltanat", anlam: "Büyük Selçuklu Devletinde devlet işlerinin görüşülüp karara bağlandığı en yüksek yönetim organıdır. Sultan adına vezir başkanlık ederdi.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Maliye ve adalet işleri Divan-ı Saltanatta görüşülürdü." },
  { terim: "Vezir", anlam: "Hükümdardan sonra devlet yönetiminde en yetkili kişidir. Divana başkanlık eder, maliye ve idari işleri denetlerdi.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Vezir, sultanın yokluğunda devleti yönetti." },
  { terim: "Şıhne", anlam: "Selçuklularda şehirlerin güvenliğini ve düzenini sağlamakla görevli askeri vali yardımcısıdır. Gerektiğinde vergi toplama işine de karışırdı.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Şıhne, şehirdeki asayişi sağlamakla yükümlüydü." },
  { terim: "Mülk arazi", anlam: "Devletin kişilere tam mülkiyet hakkı tanıyarak verdiği topraklardır. Sahibi toprağı satabilir, bağışlayabilir veya miras bırakabilirdi.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Mülk arazinin geliri doğrudan sahibine kalırdı." },
  { terim: "Vakıf arazi", anlam: "Geliri din, eğitim ve sosyal hizmet kurumlarına ayrılmak üzere devletin ayırdığı topraklardır. Satılması ve miras bırakılması yasaktı.", ders: "Tarih", konu: "İslamiyet Sonrası Türk Devletleri", ornek: "Medresenin giderleri vakıf arazi gelirlerinden karşılanırdı." },
  { terim: "Tımar sistemi", anlam: "Osmanlıda üretimden alınan verginin, asker yetiştirme ve hizmet karşılığında sipahi adı verilen görevlilere bırakıldığı düzendir. Toprağın mülkiyeti devlette, kullanım hakkı reayadaydı.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Tımar sistemi sayesinde hazineden para çıkmadan büyük bir ordu besleniyordu." },
  { terim: "Zeamet", anlam: "Yıllık geliri belirli bir sınırın üzerinde olan ve tımar sisteminde üst basamağı oluşturan dirlik türüdür. Sipahinin yanı sıra sancak beyi ve subaşı gibi görevlilere verilirdi.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Zeamet sahibi, gelirinin bir bölümüyle atlı asker beslerdi." },
  { terim: "Has arazi", anlam: "Geliri padişaha, hanedan üyelerine ya da yüksek dereceli devlet görevlilerine ayrılan en büyük dirlik türüdür.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Geliri en yüksek olan topraklara has denirdi." },
  { terim: "Kapıkulu", anlam: "Osmanlıda padişaha doğrudan bağlı, maaşlı ve merkezde görev yapan asker sınıfıdır. Yeniçeri, cebeci, topçu ve sipahi bölükleri bu sınıfa girer.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kapıkulu askerleri merkez ordusunun bel kemiğiydi." },
  { terim: "Yeniçeri Ocağı", anlam: "Kapıkulu piyadesinin en kalabalık ve etkili bölüğüdür. On dördüncü yüzyılda kurulmuş, 1826'da kaldırılmıştır.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Yeniçeri Ocağı bozulunca devlet düzeni de sarsıldı." },
  { terim: "Devşirme", anlam: "Hristiyan tebaadan küçük yaşta çocukların toplanarak Müslüman olarak yetiştirilmesi ve devlet hizmetine alınması uygulamasıdır. Genellikle Kapıkulu ve Enderun için kullanılmıştır.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Devşirme ile yetişen pek çok kişi sadrazamlığa kadar yükselmiştir." },
  { terim: "Enderun", anlam: "Sarayda devlet adamı yetiştirmek üzere kurulan iç eğitim okuludur. Devşirilen çocuklar burada dil, edep ve devlet yönetimi öğrenirdi.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Enderunda yetişen çoğu görevli yüksek makamlara geldi." },
  { terim: "Divan-ı Hümayun", anlam: "Padişah adına devlet işlerinin görüşüldüğü en yüksek yönetim ve yargı organıdır. Üyeleri veziriazam, kazasker, defterdar ve nişancıydı.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Önemli davalar Divan-ı Hümayunda görüşülürdü." },
  { terim: "Kazasker", anlam: "Divan-ı Hümayunda adalet ve eğitim işlerinden sorumlu üyedir. Kadı ve müderris atamalarını yapar, davalara bakardı.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kazasker, kadıların tayin ve azil işlerini yürütürdü." },
  { terim: "Defterdar", anlam: "Devletin mali işlerini yürüten ve bütçeyi hazırlayan divan üyesidir. Vergilerin toplanmasını ve harcamaların denetimini yapardı.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Defterdar, hazinenin gelir ve giderini hesaplardı." },
  { terim: "Nişancı", anlam: "Ferman ve beratlara padişahın tuğrasını çeken, ayrıca tapu ve kadastro işlerini yürüten divan üyesidir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Yazışmaların düzeni nişancının sorumluluğundaydı." },
  { terim: "Reisülküttap", anlam: "Divanda yazışma ve dış yazışma işlerinden sorumlu görevlidir. Zamanla Osmanlının dış işleri bakanı konumuna yaklaşmıştır.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Yabancı devletlerle yazışmaları reisülküttap yürütürdü." },
  { terim: "Şeyhülislam", anlam: "İlmiye sınıfının en yüksek makamındaki din bilginidir. Verdiği fetva, alınacak kararların dine uygunluğunu gösterirdi.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Şeyhülislamın fetvası olmadan savaş ilan edilmezdi." },
  { terim: "Kaptan-ı Derya", anlam: "Osmanlı donanmasının en yetkili komutanıdır. Deniz seferlerini yönetir, tersane ve gemi yapımını denetlerdi.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kaptan-ı Derya, donanmayı Akdeniz'e çıkardı." },
  { terim: "Kadı", anlam: "Bir kaza bölgesinin hem yöneticisi hem de yargıcı olan görevlidir. Şer'i ve örfi hukuka göre davaları görür, nikâh ve vakıf işlerini de yürütürdü.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kadı, mahallelinin davasını divanda karara bağladı." },
  { terim: "Muhtesip", anlam: "Çarşı ve pazarı denetleyen, fiyat ve ölçü birimlerinin doğruluğunu kontrol eden görevlidir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Muhtesip, bozuk mal satan esnafa ceza kesti." },
  { terim: "Müsadere", anlam: "Devlet görevlilerinin yolsuzluk yapması ya da görevden alınması durumunda mallarına devletçe el konulmasıdır. Merkezi otoriteyi güçlü tutmayı amaçlardı.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Müsadere yoluyla devlet, Müslüman görevlilerin mal varlığına el koyabilirdi." },
  { terim: "Millet sistemi", anlam: "Gayrimüslim toplulukların kendi din, eğitim ve aile işlerinde kendi dini liderlerine bağlı olarak özerk biçimde örgütlenmesidir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Millet sistemi, farklı inanç topluluklarının iç işlerini kendilerinin yürütmesini sağladı." },
  { terim: "Sened-i İttifak", anlam: "1808'de ayanlar ile devlet arasında imzalanan ve ayanların varlığının devletçe tanınmasını sağlayan belgedir. Osmanlıda anayasal gelişmelerin ilk adımı sayılır.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Sened-i İttifak padişahın yetkilerini sınırlayan ilk belge kabul edilir." },
  { terim: "Tanzimat Fermanı", anlam: "1839'da ilan edilen, can ve mal güvenliği ile kanun önünde eşitlik ilkelerini getiren düzenlemedir. Gülhane Hatt-ı Hümayunu olarak da bilinir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Tanzimat Fermanı ile vergi adaleti sağlanmaya çalışıldı." },
  { terim: "Islahat Fermanı", anlam: "1856'da ilan edilen, gayrimüslim tebaanın haklarını genişleten ve memuriyet ile eğitim alanında eşitlik getiren düzenlemedir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Islahat Fermanı gayrimüslimlere devlet memuru olma hakkı tanıdı." },
  { terim: "Kanun-i Esasi", anlam: "1876'da ilan edilen ve Osmanlının ilk anayasası sayılan temel kanundur. Padişahın yetkilerini koruduğu bir meşruti yönetim kurmuştur.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kanun-i Esasi ile ilk Osmanlı parlamentosu açıldı." },
  { terim: "I. Meşrutiyet", anlam: "1876'da Kanun-i Esasi'nin ilan edilmesiyle başlayan, halkın seçtiği meclisin kısmen yönetime katıldığı dönemdir. II. Abdülhamit tarafından 1878'de sona erdirilmiştir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "I. Meşrutiyet kısa sürmüş olsa da meclis fikrini halka tanıttı." },
  { terim: "II. Meşrutiyet", anlam: "1908'de İttihat ve Terakki Cemiyetinin çabalarıyla Kanun-i Esasi'nin yeniden yürürlüğe girmesiyle başlayan dönemdir. Seçimler yenilenmiş ve siyasi partiler çoğalmıştır.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "II. Meşrutiyet siyasal hayata canlılık getirdi." },
  { terim: "Meclis-i Mebusan", anlam: "Osmanlıda halk tarafından seçilen milletvekillerinden oluşan meclis kanadıdır. Kanun teklif etme ve bütçeyi görüşme yetkisi vardı.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Meclis-i Mebusan 1920'de Misak-ı Milliyi kabul etti." },
  { terim: "Ayan Meclisi", anlam: "Osmanlı parlamentosunun padişah tarafından atanan üyelerden oluşan kanadıdır. Mebusan Meclisinden geçen kanunları incelerdi.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Ayan Meclisi üyeleri padişah tarafından seçilirdi." },
  { terim: "Duyun-ı Umumiye", anlam: "1881'de kurulan ve Osmanlının dış borçlarını alacaklı devletler adına tahsil eden idaredir. Tuz, tütün ve içki gibi gelir kaynaklarını denetlemiştir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Duyun-ı Umumiye Osmanlının mali bağımsızlığını zedeledi." },
  { terim: "Kapitülasyonlar", anlam: "Yabancı devlet vatandaşlarına Osmanlı topraklarında ticari ve hukuki ayrıcalıklar tanıyan antlaşmalardır. Zamanla Osmanlı ekonomisine ağır zarar vermiştir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kapitülasyonlar Lozan Antlaşması ile kaldırılmıştır." },
  { terim: "Lale Devri", anlam: "1718-1730 arasında sanat, edebiyat ve kültür alanında gelişmelerin yaşandığı, Batıyla ilişkilerin arttığı dönemdir. İlk matbaa ve itfaiye bu dönemde kurulmuştur.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Lale Devrinde ilk Türk matbaası açıldı." },
  { terim: "Nizam-ı Cedit", anlam: "III. Selim döneminde kurulan, Batılı eğitim ve disiplinle yetiştirilmiş yeni asker ocakları ile yapılan ıslahatların adıdır. Yeniçerilerin tepkisiyle sona ermiştir.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Nizam-ı Cedit ordusu Avrupa tarzında eğitildi." },
  { terim: "İlmiye sınıfı", anlam: "Osmanlıda eğitim, adalet ve din işlerini yürüten ulema sınıfıdır. Kadı, müderris ve şeyhülislam bu sınıfa mensuptur.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Kadılar ve müderrisler ilmiye sınıfına bağlıydı." },
  { terim: "Seyfiye sınıfı", anlam: "Osmanlıda yönetim ve askerlik işlerini yürüten, kılıç ehli sayılan görevliler sınıfıdır. Veziriazam, sancak beyi ve yeniçeri ağası bu sınıftandır.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Seyfiye sınıfı devletin yönetim ve askerlik işlerine bakardı." },
  { terim: "Vaka-i Hayriye", anlam: "1826'da II. Mahmut tarafından Yeniçeri Ocağının kaldırılması olayıdır. Yerine Asakir-i Mansure-i Muhammediye ordusu kurulmuştur.", ders: "Tarih", konu: "Osmanlı Devleti", ornek: "Vaka-i Hayriye ile merkezi otorite güçlendirildi." },
  { terim: "Amasya Genelgesi", anlam: "1919'da Mustafa Kemal'in yayımladığı ve milletin bağımsızlığını yine milletin azim ve kararının kurtaracağını bildiren belgedir. Kurtuluş Savaşının gerekçesi ve yöntemi ilk kez açıklanmıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Amasya Genelgesi ulusal mücadelenin ilk çağrısı sayılır." },
  { terim: "Erzurum Kongresi", anlam: "1919 Temmuzunda toplanan ve Doğu Anadolu illerinin temsilcilerinin katıldığı kongredir. Manda ve himaye ilk kez reddedilmiş, geçici hükûmet kurulması kararı alınmıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Erzurum Kongresinde millî sınırlar ilk kez çizildi." },
  { terim: "Sivas Kongresi", anlam: "1919 Eylülünde toplanan ve bütün ulusal cemiyetlerin Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adıyla birleştirildiği kongredir. Erzurum Kongresi kararları genişletilerek kabul edilmiştir.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Sivas Kongresinde bütün millî cemiyetler tek çatı altında toplandı." },
  { terim: "Misak-ı Milli", anlam: "1920'de Son Osmanlı Mebusan Meclisinde kabul edilen ve millî sınırlar ile tam bağımsızlık esaslarını belirleyen kararlar bütünüdür.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Misak-ı Milli, Türk vatanının sınırlarını çizdi." },
  { terim: "Büyük Millet Meclisi", anlam: "1920 Nisanında Ankara'da açılan ve millî iradeyi temsil eden meclistir. Kurtuluş Savaşını yönetmiş ve yeni devletin temelini atmıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Büyük Millet Meclisi olağanüstü yetkilerle açıldı." },
  { terim: "Mondros Ateşkes Antlaşması", anlam: "1918'de imzalanan ve Osmanlı Devletinin Birinci Dünya Savaşından çekilmesini sağlayan ateşkes antlaşmasıdır. İtilaf Devletlerine geniş işgal yetkisi tanımıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Mondros sonrası Anadolu işgallere açık hâle geldi." },
  { terim: "Sevr Antlaşması", anlam: "1920'de imzalanan ancak Türk milletinin direnişi nedeniyle yürürlüğe girmeyen barış antlaşmasıdır. Anadoluda küçük bir bölge dışında Türk vatanını parçalamayı öngörüyordu.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Sevr Antlaşması uygulanamadı ve tarihe geçti." },
  { terim: "Tekalif-i Milliye Emirleri", anlam: "Sakarya Savaşı öncesinde ordunun ihtiyaçlarını karşılamak için Mustafa Kemal'in yayımladığı emirlerdir. Halktan yiyecek, giyecek ve silah toplanmasını öngörür.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Tekalif-i Milliye Emirleri ile ordu kısa sürede donatıldı." },
  { terim: "Sakarya Meydan Muharebesi", anlam: "1921'de kazanılan ve Türk ordusunun savunma savaşını saldırıya çevirdiği büyük muharebedir. Sonuçları Kars ve Ankara antlaşmalarını hazırlamıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Sakarya zaferi ulusal mücadelenin dönüm noktası oldu." },
  { terim: "Büyük Taarruz", anlam: "1922 Ağustosunda Başkomutanlık Meydan Muharebesiyle sonuçlanan ve işgali sona erdiren taarruzdur. İzmir'in kurtarılmasıyla savaş fiilen bitmiştir.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Büyük Taarruz sonrası Mudanya Ateşkesi imzalandı." },
  { terim: "Mudanya Ateşkes Antlaşması", anlam: "1922 Ekiminde imzalanan ve Doğu Trakya'nın savaş yapılmadan geri alınmasını sağlayan ateşkestir. Lozan görüşmelerinin yolunu açmıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Mudanya ile silahlar sustu ve diplomasi dönemi başladı." },
  { terim: "Lozan Antlaşması", anlam: "1923'te imzalanan ve yeni Türk devletinin bağımsızlığını uluslararası düzeyde kabul ettiren barış antlaşmasıdır. Kapitülasyonlar kaldırılmış, sınırlar büyük ölçüde Misak-ı Millîye göre çizilmiştir.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Lozan Antlaşması Türkiye Cumhuriyetinin tapusu sayılır." },
  { terim: "Ankara Antlaşması", anlam: "1921'de Fransa ile imzalanan ve Türkiye-Suriye sınırını belirleyen antlaşmadır. Fransa, TBMM hükûmetini tanıyan ilk İtilaf Devleti olmuştur.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Ankara Antlaşması ile güney cephesinde çatışmalar bitti." },
  { terim: "Kars Antlaşması", anlam: "1921'de Sovyet yönetimindeki Kafkas cumhuriyetleriyle imzalanan ve doğu sınırını kesinleştiren antlaşmadır. Moskova Antlaşmasının hükümleri tekrarlanmıştır.", ders: "Tarih", konu: "Kurtuluş Savaşı", ornek: "Kars Antlaşması doğu sınırımızı güvence altına aldı." },
  { terim: "Saltanatın kaldırılması", anlam: "1922'de TBMM kararıyla padişahlık kurumunun sona erdirilmesidir. Böylece millî egemenliğin önündeki en büyük engel kaldırılmıştır.", ders: "Tarih", konu: "Atatürk Dönemi", ornek: "Saltanatın kaldırılmasıyla cumhuriyete giden yol açıldı." },
  { terim: "Cumhuriyetin ilanı", anlam: "1923 Ekiminde TBMM tarafından devlet biçiminin cumhuriyet olarak belirlenmesidir. Mustafa Kemal ilk cumhurbaşkanı seçilmiştir.", ders: "Tarih", konu: "Atatürk Dönemi", ornek: "Cumhuriyetin ilanıyla devlet başkanlığı sorunu çözüldü." },
  { terim: "Halifeliğin kaldırılması", anlam: "1924'te TBMM kararıyla halifelik kurumunun sona erdirilmesidir. Laiklik yolunda atılan en önemli adımlardan biridir.", ders: "Tarih", konu: "Atatürk Dönemi", ornek: "Halifeliğin kaldırılması laikleşme sürecini hızlandırdı." },
  { terim: "Teşkilat-ı Esasiye Kanunu", anlam: "1921'de kabul edilen ve yeni devletin ilk anayasası olan temel kanundur. Egemenliğin kayıtsız şartsız millete ait olduğunu belirtir.", ders: "Tarih", konu: "Atatürk Dönemi", ornek: "Teşkilat-ı Esasiye millî egemenlik ilkesini hukuka bağladı." },
  { terim: "Takrir-i Sükûn Kanunu", anlam: "1925'te çıkarılan ve hükûmete ayaklanmaları bastırmak için olağanüstü yetkiler veren kanundur. Şeyh Sait İsyanı sonrası düzeni sağlamak amacıyla kullanılmıştır.", ders: "Tarih", konu: "Atatürk Dönemi", ornek: "Takrir-i Sükûn Kanunu ile ayaklanmalar bastırıldı." },
  { terim: "Falez", anlam: "Dalgaların kıyıdaki yamaçları aşındırmasıyla oluşan dik ve yüksek kıyı yarımıdır. Yalıyar adı da verilir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Karadeniz kıyılarında falezler yaygındır." },
  { terim: "Tombolo", anlam: "Kıyı oku ile bir adanın ya da kıyının, dalga ve akıntıların taşıdığı alüvyonla birleşmesiyle oluşan yer şeklidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Kapıdağ Yarımadası bir tombolo örneğidir." },
  { terim: "Kıyı oku", anlam: "Kıyı boyunca taşınan kum ve çakılın denize doğru uzanan ince bir set oluşturmasıyla meydana gelen yer şeklidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Dalga ve akıntılar kıyı okunu denize doğru uzatmıştır." },
  { terim: "Lagün", anlam: "Kıyı oku ya da setlerin denizden ayırdığı sığ ve durgun su kütlesidir. Deniz kulağı da denir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Büyükçekmece Gölü bir lagündür." },
  { terim: "Delta ovası", anlam: "Bir akarsuyun denize ya da göle döküldüğü yerde taşıdığı alüvyonu biriktirmesiyle oluşan düz ovadır.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Bafra Deltası Kızılırmak tarafından oluşturulmuştur." },
  { terim: "Haliç", anlam: "Denizin, akarsu ağzındaki vadilere sokulmasıyla oluşan ve karmaşık bir kıyı çizgisi yaratan girintidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "İstanbul Boğazı çevresindeki Haliç bu şekle örnektir." },
  { terim: "Kanyon vadi", anlam: "Akarsuyun dirençli tabakaları derin biçimde yarmasıyla oluşan, yamaçları çok dik ve derin vadidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Köprülü Kanyon bu vadilerin en bilinen örneğidir." },
  { terim: "Peribacası", anlam: "Sel sularının ve rüzgârın tüf örtüsünü aşındırmasıyla altta sert bir şapkanın koruduğu dirençli kaya sütunlarından oluşan yer şeklidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Kapadokya peribacalarıyla ünlüdür." },
  { terim: "Lapya", anlam: "Karstik arazide yağış sularının kireç taşını yüzeyden eritmesiyle oluşan küçük oluk ve çukurluklardır.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Kireç taşı yüzeyinde onlarca lapya oluşmuştu." },
  { terim: "Düden", anlam: "Karstik arazide yüzey suyunun yer altına girdiği noktadır. Su yutan ya da yutan yarık biçiminde görülür.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Kırkgöz Düdeni suları yer altına indirir." },
  { terim: "Obruk", anlam: "Karstik bölgelerde yer altındaki mağara tavanlarının çökmesiyle oluşan derin ve geniş çukurluktur.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Konya ovasında obruklar sık görülür." },
  { terim: "Polye", anlam: "Karstik arazide oluşmuş, tabanı düz ve geniş olan büyük çukurluktur. Çevresi yüksek kireç taşı sırtlarıyla çevrilidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Elmalı Ovası bir polye örneğidir." },
  { terim: "Sirk", anlam: "Buzulun yamaçta oyduğu, çoğunlukla tabanında göl bulunan çanak biçimli çukurluktur. Sirk gölleri bu çanaklarda oluşur.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Zirvedeki sirkte küçük bir buzul gölü vardı." },
  { terim: "Tekne vadi", anlam: "Buzulun geçtiği vadilerin buzul aşındırmasıyla U biçimini almasıyla oluşan vadidir. Tabanı geniş ve yamaçları diktir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Buzul vadileri tekne vadi biçimindedir." },
  { terim: "Moren", anlam: "Buzulun taşıdığı kaya, kum ve çakılın buzul erirken bıraktığı birikimdir. Buzulun alt, yan ve son morenleri vardır.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Buzulun çekilmesiyle geride kalın bir moren örtüsü kaldı." },
  { terim: "Heyelan", anlam: "Eğimli yamaçlardaki toprak ve kaya kütlelerinin yer çekimi etkisiyle aşağı doğru kayması olayıdır. Toprak kayması da denir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Şiddetli yağıştan sonra yamaçta heyelan oldu." },
  { terim: "Erozyon", anlam: "Toprağın su, rüzgâr ve diğer dış etkenlerle taşınıp başka yerlere sürüklenmesi olayıdır. Bitki örtüsünün yok olduğu alanlarda hızlanır.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Erozyon tarım topraklarını verimsizleştirir." },
  { terim: "Plato", anlam: "Çevresine göre yüksekte kalan ve genellikle akarsularla yarılmış geniş düzlüktür. Yüksek ve alçak platolar biçiminde ayrılır.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Anadolunun iç kesimleri geniş platolarla kaplıdır." },
  { terim: "Ova", anlam: "Çevresine göre alçakta bulunan ve geniş yer tutan düz arazi biçimidir. Akarsu, göl ve deniz birikimiyle oluşabilir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Çukurova Türkiyenin en büyük delta ovasıdır." },
  { terim: "Volkan konisi", anlam: "Volkanik maddelerin ağız çevresinde birikmesiyle oluşan koni biçimli yükseltidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Ağrı Dağı büyük bir volkan konisidir." },
  { terim: "Kaldera", anlam: "Büyük bir volkanın patlamayla çökmesi sonucu oluşan çok geniş çukurluktur. Zamanla suyla dolup göl hâline gelebilir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Kalderanın tabanında büyük bir göl oluşmuştu." },
  { terim: "Maar", anlam: "Volkanik patlamanın gaz ve su buharıyla birlikte çevreyi çukurlar biçiminde bırakmasıyla oluşan küçük göl çanağıdır.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Meke Gölü bir maar içinde yer alır." },
  { terim: "Horst", anlam: "Yer kabuğundaki kırılmalarda çevresine göre yüksekte kalan ve blok hâlinde yükselen yer şeklidir.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Kırıklı dağlar horst ve grabenlerden oluşur." },
  { terim: "Graben", anlam: "Kırılmalarla çökmüş ve iki yanı faylı, uzun çukurluk biçimindeki yer şeklidir. Genellikle akarsu vadisini izler.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Gediz Grabeni çöküntü ovalarıyla doludur." },
  { terim: "Fay hattı", anlam: "Yer kabuğundaki blokların birbirine göre hareket ettiği kırık hattıdır. Enerji birikimi boşalınca deprem oluşur.", ders: "Coğrafya", konu: "Yer Şekilleri", ornek: "Türkiye aktif fay hatları üzerinde yer alır." },
  { terim: "Ekvatoral iklim", anlam: "Ekvator çevresinde görülen, her mevsim bol yağışlı ve sıcak geçen iklimdir. Yıllık sıcaklık farkı çok azdır.", ders: "Coğrafya", konu: "İklim", ornek: "Amazon havzasında ekvatoral iklim hüküm sürer." },
  { terim: "Muson iklimi", anlam: "Mevsimler arasında yön değiştiren muson rüzgârlarının yağış getirdiği iklimdir. Yazlar çok yağışlı, kışlar kurak geçer.", ders: "Coğrafya", konu: "İklim", ornek: "Güney Asyada muson iklimi pirinç tarımını mümkün kılar." },
  { terim: "Çöl iklimi", anlam: "Yıllık yağışın çok az olduğu, günlük sıcaklık farkının çok yüksek bulunduğu kurak iklimdir.", ders: "Coğrafya", konu: "İklim", ornek: "Sahra çöl ikliminin en geniş alanıdır." },
  { terim: "Akdeniz iklimi", anlam: "Yazları sıcak ve kurak, kışları ılık ve yağışlı geçen iklim tipidir. Maki bitki örtüsüyle tanınır.", ders: "Coğrafya", konu: "İklim", ornek: "Antalya Akdeniz ikliminin etkisi altındadır." },
  { terim: "Karasal iklim", anlam: "Kışları soğuk, yazları sıcak ve kurak geçen, sıcaklık farkının yüksek olduğu iklim tipidir.", ders: "Coğrafya", konu: "İklim", ornek: "Anadolunun iç kesimlerinde karasal iklim görülür." },
  { terim: "Tundra iklimi", anlam: "Kutup bölgelerine yakın alanlarda görülen, çok soğuk ve kısa yazlarla beliren iklimdir. Ağaç yetişmez, yosun ve çalılar bulunur.", ders: "Coğrafya", konu: "İklim", ornek: "Tundra ikliminde tarım yapılamaz." },
  { terim: "Kutup iklimi", anlam: "Kutuplarda görülen, sıcaklığın yıl boyunca sıfırın altında kaldığı iklim tipidir. Bitki örtüsü yoktur.", ders: "Coğrafya", konu: "İklim", ornek: "Kutup ikliminde sürekli buzullar bulunur." },
  { terim: "Step iklimi", anlam: "İlkbahar yağışlarıyla yeşeren, yazın kuruyan otsu bitki örtüsünün görüldüğü yarı kurak iklimdir.", ders: "Coğrafya", konu: "İklim", ornek: "İç Anadoluda step iklimi geniş alan kaplar." },
  { terim: "Sıcaklık terselmesi", anlam: "Normalde yükseldikçe azalan hava sıcaklığının, soğuk hava tabanı çökerek alçak kesimlerde daha düşük olması durumuyla oluşur. Çukur ovalarda sis ve don olayını artırır.", ders: "Coğrafya", konu: "İklim", ornek: "Kışın çukurlarda sıcaklık terselmesi görülür." },
  { terim: "İzobar", anlam: "Haritalarda eşit basınçlı noktaları birleştiren eğridir. Aralarındaki sıklık basınç farkının büyüklüğünü gösterir.", ders: "Coğrafya", konu: "İklim", ornek: "İzobarların sıklaştığı yerde rüzgâr kuvvetlenir." },
  { terim: "İzoterm", anlam: "Haritalarda eşit sıcaklıktaki noktaları birleştiren eğridir. Sıcaklık dağılışını göstermek için kullanılır.", ders: "Coğrafya", konu: "İklim", ornek: "Ocak ayı izotermleri kuzeyde daha sık geçer." },
  { terim: "Yağış rejimi", anlam: "Bir yerde yağışın yıl içindeki dağılış biçimidir. Düzenli ve düzensiz yağış rejimleri ayırt edilir.", ders: "Coğrafya", konu: "İklim", ornek: "Karadeniz kıyılarında yağış rejimi düzenlidir." },
  { terim: "Alçak basınç merkezi", anlam: "Havanın yükselerek seyreldiği ve çevreden hava çektiği basınç alanıdır. Yükselen hava soğuyup yağış bırakır.", ders: "Coğrafya", konu: "İklim", ornek: "Alçak basınç merkezleri genellikle yağışlıdır." },
  { terim: "Meltem rüzgârı", anlam: "Gün içinde kara ile deniz ya da vadi ile dağ arasındaki sıcaklık farkından doğan, yönü günlük değişen hafif rüzgârdır.", ders: "Coğrafya", konu: "İklim", ornek: "Yaz akşamları deniz meltemi serinlik getirir." },
  { terim: "Föhn rüzgârı", anlam: "Dağ yamacını aşıp alçalırken ısınan ve kuruyan yerel rüzgârdır. Eriyerek nemini bıraktığı için sıcak eser.", ders: "Coğrafya", konu: "İklim", ornek: "Föhn rüzgârı karları hızla eritebilir." },
  { terim: "Cephe yağışı", anlam: "Sıcak ve soğuk hava kütlelerinin karşılaştığı cephe hattı boyunca sıcak havanın yükselmesiyle oluşan yağıştır.", ders: "Coğrafya", konu: "İklim", ornek: "Orta kuşakta cephe yağışları yaygındır." },
  { terim: "Yükselim yağışı", anlam: "Isınan havanın yükselip soğumasıyla oluşan, genellikle öğleden sonra görülen sağanak yağıştır. Konveksiyonel yağış da denir.", ders: "Coğrafya", konu: "İklim", ornek: "Ekvator çevresinde yükselim yağışları her gün görülür." },
  { terim: "Bağıl nem", anlam: "Havanın belli bir sıcaklıkta taşıyabileceği en yüksek nem miktarına göre taşıdığı nemin yüzdesidir. Sıcaklık artınca bağıl nem azalır.", ders: "Coğrafya", konu: "İklim", ornek: "Hava ısındıkça bağıl nem oranı düşer." },
  { terim: "Kuraklık", anlam: "Yağışın uzun süre ortalamanın altında kalmasıyla su kaynaklarının yetersizleşmesi durumudur. Tarım ve içme suyu üzerinde ağır etki bırakır.", ders: "Coğrafya", konu: "İklim", ornek: "Kuraklık nedeniyle barajlardaki su seviyesi düştü." },
  { terim: "Hâkim rüzgâr", anlam: "Bir yerde yıl içinde en sık esen rüzgâr yönüdür. Rüzgâr gülü grafikleriyle gösterilir.", ders: "Coğrafya", konu: "İklim", ornek: "Fabrika bacaları hâkim rüzgâr yönüne göre yerleştirilir." },
  { terim: "Nadas", anlam: "Tarlanın bir yıl ekilip bir yıl boş bırakılarak dinlendirilmesi uygulamasıdır. Toprağın verimini korumayı amaçlar.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Nadas uygulanan tarlada bu yıl buğday ekilmedi." },
  { terim: "Nöbetleşe ekim", anlam: "Aynı tarlada değişik ürünlerin sırayla yetiştirilmesidir. Toprak yorgunluğunu azaltır ve verimi artırır.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Çiftçi nöbetleşe ekim sayesinde toprağı verimli tutar." },
  { terim: "İntansif tarım", anlam: "Modern yöntemler, gübre ve sulama kullanılarak birim alandan yüksek verim alınan tarım biçimidir. Yoğun tarım da denir.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Seracılık intansif tarımın en güzel örneğidir." },
  { terim: "Ekstansif tarım", anlam: "Geleneksel yöntemlerle, birim alandan düşük verim alınan yaygın tarım biçimidir. Geniş araziler gerektirir.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Nadaslı tarım ekstansif tarıma örnektir." },
  { terim: "Seracılık", anlam: "Sebze ve meyvenin cam ya da plastik örtü altında, iklim koşullarından bağımsız yetiştirilmesidir. Isıtma ve sulama gerektirir.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Antalya seracılıkta ülkemizin önde gelen ilidir." },
  { terim: "Organize Sanayi Bölgesi", anlam: "Sanayi tesislerinin altyapısı hazır alanlarda toplu hâlde kurulmasını sağlayan bölgedir. Çevre kirliliğini ve maliyeti azaltmayı amaçlar.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Yeni fabrika organize sanayi bölgesinde açıldı." },
  { terim: "Transit ticaret", anlam: "Bir ürünün üretildiği ve tüketildiği ülke dışındaki başka bir ülkeden geçirilerek taşınmasıdır. Boğazlar ve limanlar bu ticarette önemlidir.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "İstanbul ve Çanakkale boğazları transit ticaret yollarıdır." },
  { terim: "Kültür turizmi", anlam: "Tarihi eserler, müzeler ve geleneksel değerleri görmek amacıyla yapılan seyahatleri kapsayan turizm türüdür.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Kapadokya kültür turizminin merkezlerindendir." },
  { terim: "İthalat", anlam: "Bir ülkenin başka ülkelerden mal ve hizmet satın almasıdır. Dış alım da denir.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Artan enerji ithalatı cari açığı büyütüyor." },
  { terim: "İhracat", anlam: "Bir ülkenin ürettiği mal ve hizmetleri başka ülkelere satmasıdır. Dış satım da denir.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Tekstil ihracatı ülke ekonomisine önemli katkı sağlar." },
  { terim: "Dış ticaret açığı", anlam: "İthalatın ihracattan fazla olması nedeniyle oluşan olumsuz farktır. Ülkenin döviz kaybına yol açar.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Dış ticaret açığı döviz rezervlerini eritiyor." },
  { terim: "Jeotermal enerji", anlam: "Yer altındaki sıcak su ve buhardan elde edilen yenilenebilir enerji türüdür. Elektrik üretimi ve ısıtma amacıyla kullanılır.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Denizli jeotermal enerji santraliyle elektrik üretir." },
  { terim: "Yaylak", anlam: "Hayvanların yazın otlatıldığı, yüksek ve serin çayırlık alandır. Mera ile birlikte hayvancılığın temelini oluşturur.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Sürü yazın yaylaya çıkarıldı." },
  { terim: "Millî park", anlam: "Bilimsel ve estetik yönden değerli, koruma altına alınmış doğal ve kültürel alandır. İçinde yapılaşma sınırlandırılır.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Yedigöller Millî Parkı koruma altındadır." },
  { terim: "Liman", anlam: "Gemilerin yanaşıp yük ve yolcu indirip bindirebildiği, dalgalardan korunmuş yapay ya da doğal su alanıdır. Dış ticaretin ana kapısıdır.", ders: "Coğrafya", konu: "Ekonomi Coğrafyası", ornek: "Ambarlı Limanı ülkenin en yoğun limanlarındandır." },
  { terim: "Anayasa", anlam: "Devletin temel kuruluşunu, organlarını ve temel hak ve özgürlükleri düzenleyen, diğer bütün kanunların üstünde yer alan temel kanundur.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Anayasaya aykırı bir kanun iptal edilir." },
  { terim: "Kanun", anlam: "Türkiye Büyük Millet Meclisi tarafından kabul edilen ve Cumhurbaşkanınca yayımlanan genel ve bağlayıcı hukuk kuralıdır.", ders: "Vatandaşlık", konu: "Hukukun Kaynakları", ornek: "Kanun Resmî Gazetede yayımlanarak yürürlüğe girer." },
  { terim: "Cumhurbaşkanlığı kararnamesi", anlam: "Cumhurbaşkanının yürütme yetkisine ilişkin konularda çıkardığı düzenleyici işlemdir. Konusu ve sınırları Anayasada belirtilmiştir.", ders: "Vatandaşlık", konu: "Hukukun Kaynakları", ornek: "Konuya ilişkin cumhurbaşkanlığı kararnamesi yayımlandı." },
  { terim: "Yönetmelik", anlam: "Cumhurbaşkanı, bakanlıklar ve kamu tüzel kişilerinin kanunların uygulanışını göstermek için çıkardığı düzenleyici işlemdir.", ders: "Vatandaşlık", konu: "Hukukun Kaynakları", ornek: "Bakanlık, sınav usulünü yönetmelikle belirledi." },
  { terim: "Hukuk devleti", anlam: "Devletin bütün işlem ve eylemlerinin hukuk kurallarına bağlı olduğu ve kişi haklarının yargı güvencesi altında bulunduğu devlet anlayışıdır.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Hukuk devletinde hiç kimse yargı denetimi dışında kalamaz." },
  { terim: "Egemenlik", anlam: "Devletin ülke üzerinde kurduğu en üstün buyurma gücüdür. Anayasaya göre egemenlik kayıtsız şartsız millete aittir.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Egemenlik milletin elindedir ve nasıl kullanılacağı anayasada yazılıdır." },
  { terim: "Kuvvetler ayrılığı", anlam: "Yasama, yürütme ve yargı yetkilerinin farklı organlara verilerek birbirini denetlemesini öngören ilkedir.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Kuvvetler ayrılığı keyfi yönetimi engeller." },
  { terim: "Yasama", anlam: "Kanun yapma, değiştirme ve kaldırma yetkisidir. Türkiyede bu yetki Türkiye Büyük Millet Meclisine aittir.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Yasama yetkisi devredilemez." },
  { terim: "Yürütme", anlam: "Kanunları uygulama ve devlet işlerini yürütme yetkisidir. Türkiyede Cumhurbaşkanı tarafından kullanılır.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Yürütme organı kanunları uygular." },
  { terim: "Yargı", anlam: "Bağımsız mahkemeler eliyle uyuşmazlıkları çözme ve hukuku uygulama yetkisidir.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Yargı yetkisi Türk milleti adına kullanılır." },
  { terim: "Temel hak ve özgürlükler", anlam: "Anayasa ile kişilere tanınan ve devletin dokunamayacağı haklardır. Kişi hakları, sosyal haklar ve siyasi haklar olarak sınıflandırılır.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Eğitim hakkı temel hak ve özgürlükler arasındadır." },
  { terim: "Kişi dokunulmazlığı", anlam: "Herkesin yaşama, maddi ve manevi varlığını koruma ve geliştirme hakkına sahip olması ve beden bütünlüğüne dokunulamamasıdır.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Kişi dokunulmazlığı anayasal güvence altındadır." },
  { terim: "Masumiyet karinesi", anlam: "Suçluluğu hükümle sabit oluncaya kadar kimsenin suçlu sayılamayacağını belirten ilkedir. Şüphe sanık lehine yorumlanır.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Masumiyet karinesi gereği sanık suçlu ilan edilemez." },
  { terim: "Yakalama", anlam: "Bir kişinin suç işlediği şüphesiyle özgürlüğünün geçici olarak kısıtlanmasıdır. Yakalanan kişi hâkime sevk edilme hakkına sahiptir.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Yakalama işlemi tutanağa bağlanır." },
  { terim: "Tutuklama", anlam: "Yargıç kararıyla kişinin özgürlüğünün kovuşturma boyunca kısıtlanmasıdır. Ancak kuvvetli suç şüphesi ve kaçma tehlikesi varsa uygulanır.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Şüpheli hakkında tutuklama kararı verildi." },
  { terim: "Gözaltı", anlam: "Yakalanan kişinin sorgu ve soruşturma işlemleri için kolluk tarafından sınırlı süreyle alıkonulmasıdır. Gözaltı süresi kanunla sınırlandırılmıştır.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Gözaltı süresi dolunca şüpheli serbest bırakıldı." },
  { terim: "Adil yargılanma hakkı", anlam: "Herkesin bağımsız ve tarafsız mahkemeler önünde makul sürede yargılanma, savunma ve delil sunma hakkına sahip olmasıdır.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Adil yargılanma hakkı uluslararası sözleşmelerle de güvence altındadır." },
  { terim: "Mülkiyet hakkı", anlam: "Kişinin bir mal üzerinde sahiplik, kullanma ve tasarruf yetkilerini kapsayan hakkıdır. Ancak kamu yararı için kanunla sınırlandırılabilir.", ders: "Vatandaşlık", konu: "Temel Haklar", ornek: "Mülkiyet hakkı ancak kanunla sınırlanabilir." },
  { terim: "Seçme ve seçilme hakkı", anlam: "Vatandaşların oy vererek yöneticileri belirleme ve seçimlerde aday olabilme hakkıdır.", ders: "Vatandaşlık", konu: "Siyasi Haklar", ornek: "On sekiz yaşını dolduran her vatandaş seçme hakkına sahiptir." },
  { terim: "Dilekçe hakkı", anlam: "Vatandaşların kendileriyle veya kamuyla ilgili istek ve şikâyetlerini yetkili makamlara yazılı olarak bildirme hakkıdır.", ders: "Vatandaşlık", konu: "Siyasi Haklar", ornek: "Vatandaşlar dilekçe hakkını kullanarak taleplerini iletti." },
  { terim: "Sendika kurma hakkı", anlam: "Çalışanların ve işverenlerin ortak ekonomik ve sosyal çıkarlarını korumak için örgüt kurabilme hakkıdır.", ders: "Vatandaşlık", konu: "Sosyal ve Ekonomik Haklar", ornek: "İşçiler sendika kurma hakkını kullanarak örgütlendi." },
  { terim: "Toplu iş sözleşmesi", anlam: "İşçi sendikası ile işveren arasında imzalanan ve çalışma koşullarını düzenleyen sözleşmedir. Tarafların hak ve borçlarını belirler.", ders: "Vatandaşlık", konu: "Sosyal ve Ekonomik Haklar", ornek: "Toplu iş sözleşmesi zam oranını belirledi." },
  { terim: "Grev", anlam: "İşçilerin toplu iş sözleşmesi görüşmelerinde anlaşma sağlanamazsa iş bırakarak işi durdurma hakkıdır.", ders: "Vatandaşlık", konu: "Sosyal ve Ekonomik Haklar", ornek: "İşçiler grev kararı alarak üretimi durdurdu." },
  { terim: "Lokavt", anlam: "İşverenin, toplu iş sözleşmesi sürecinde anlaşmazlık hâlinde işyerinde çalışmayı geçici olarak durdurmasıdır.", ders: "Vatandaşlık", konu: "Sosyal ve Ekonomik Haklar", ornek: "İşveren lokavt ilan ederek işi tatil etti." },
  { terim: "Sosyal devlet", anlam: "Vatandaşların asgari yaşam düzeyini ve sosyal güvenliğini sağlamayı, gelir dağılımında adaleti gözetmeyi görev edinen devlet anlayışıdır.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Sosyal devlet, güçsüzleri korumak için önlem alır." },
  { terim: "Laiklik", anlam: "Din ve devlet işlerinin ayrı tutulduğu, devletin bütün dinler karşısında tarafsız kaldığı ve din özgürlüğünü güvence altına aldığı ilkedir.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Laiklik ilkesiyle vicdan ve inanç özgürlüğü korunur." },
  { terim: "Normlar hiyerarşisi", anlam: "Hukuk kurallarının birbirine üstünlük sırasına göre dizi oluşturmasıdır. Anayasa en üstte yer alır, alttaki kural üsttekine aykırı olamaz.", ders: "Vatandaşlık", konu: "Hukukun Kaynakları", ornek: "Yönetmelik kanuna aykırı olamaz, bu normlar hiyerarşisinin gereğidir." },
  { terim: "Anayasa yargısı", anlam: "Kanunların ve bazı düzenleyici işlemlerin Anayasaya uygunluğunun denetlenmesidir. Türkiyede bu denetimi Anayasa Mahkemesi yapar.", ders: "Vatandaşlık", konu: "Anayasa Hukuku", ornek: "Anayasa yargısı kanunların anayasaya uygunluğunu denetler." },
  { terim: "Anayasa Mahkemesi", anlam: "Kanunların Anayasaya uygunluğunu denetleyen, Cumhurbaşkanını ve yüksek yargı üyelerini yargılayan en yüksek anayasal yargı organıdır.", ders: "Vatandaşlık", konu: "Yargı Kurumları", ornek: "Anayasa Mahkemesi kanunun bir maddesini iptal etti." },
  { terim: "Danıştay", anlam: "İdari davalara bakan ve idarenin faaliyetleriyle ilgili görüş bildiren yüksek yargı organıdır. İdari yargının en üst merciidir.", ders: "Vatandaşlık", konu: "Yargı Kurumları", ornek: "İdari işleme karşı Danıştaya temyiz başvurusu yapıldı." },
  { terim: "Yargıtay", anlam: "Adli yargıda ilk derece mahkemelerinin kararlarını inceleyen en yüksek yargı organıdır.", ders: "Vatandaşlık", konu: "Yargı Kurumları", ornek: "Dosya temyiz üzerine Yargıtaya gönderildi." },
  { terim: "Sayıştay", anlam: "Kamu gelir ve giderlerini denetleyen, TBMM adına kamu hesaplarını inceleyen yüksek kurumdur.", ders: "Vatandaşlık", konu: "Yargı Kurumları", ornek: "Sayıştay raporu kamu harcamalarını denetledi." },
  { terim: "Hâkimler ve Savcılar Kurulu", anlam: "Hâkim ve savcıların atanması, yer değiştirmesi ve meslekten çıkarılması gibi özlük işlerini yürüten kuruldur. Yargı bağımsızlığını güvence altına almayı amaçlar.", ders: "Vatandaşlık", konu: "Yargı Kurumları", ornek: "Atama kararını Hâkimler ve Savcılar Kurulu verdi." },
  { terim: "İdari yargı", anlam: "İdarenin hukuka aykırı işlem ve eylemlerinden doğan uyuşmazlıkları çözen yargı koludur. İptal ve tam yargı davaları burada görülür.", ders: "Vatandaşlık", konu: "Yargı Kurumları", ornek: "İmar planı iptal davası idari yargıda açıldı." },
  { terim: "İdari vesayet", anlam: "Merkezi yönetimin, yerel yönetimlerin işlemlerini hukuka uygunluk yönünden denetlemesidir. Yerel yönetimin özerkliğini ortadan kaldırmaz.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Valilik, belediye kararını idari vesayet yoluyla denetledi." },
  { terim: "Merkezi yönetim", anlam: "Devlet tüzel kişiliğine bağlı olarak ülke genelinde örgütlenmiş yönetim yapısıdır. Başkent ve taşra örgütlerinden oluşur.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Kaymakamlar merkezi yönetimin taşra görevlileridir." },
  { terim: "Yerel yönetim", anlam: "Belirli bir coğrafi alanda yaşayanların ortak ihtiyaçlarını karşılamak üzere kurulan ve özerkliği bulunan kamu tüzel kişileridir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Belediye ve il özel idaresi birer yerel yönetimdir." },
  { terim: "Belediye", anlam: "Belirli bir yerleşim yerinin yerel nitelikli hizmetlerini yürüten, karar organı seçimle oluşan kamu tüzel kişisidir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Belediye, yol ve temizlik hizmetlerini yürütür." },
  { terim: "İl özel idaresi", anlam: "İl sınırları içinde yaşayanların ortak ihtiyaçlarını karşılamak üzere kurulmuş kamu tüzel kişisidir. Karar organı il genel meclisidir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "İl özel idaresi köy yollarını yaptı." },
  { terim: "Köy", anlam: "Muhtar ve ihtiyar heyeti tarafından yönetilen, mahalli ihtiyaçların karşılandığı en küçük yerleşim birimidir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Köy, kendi ihtiyaçları için imece düzenleyebilir." },
  { terim: "Muhtar", anlam: "Köy ya da mahalle halkının seçtiği, devletin temsilcisi olarak yerel hizmetleri yürüten yerel yöneticidir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Muhtar, mahalledeki sorunları belediyeye iletti." },
  { terim: "Vali", anlam: "İlde Cumhurbaşkanını ve devleti temsil eden, il yönetiminin başı olan memurdur.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Vali, ildeki bütün kamu kurumlarını denetler." },
  { terim: "Kaymakam", anlam: "İlçede devleti temsil eden ve ilçe yönetimini yürüten görevlidir. Valiye karşı sorumludur.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Kaymakam ilçedeki asayişi sağlamakla yükümlüdür." },
  { terim: "Kamu tüzel kişiliği", anlam: "Kamu hizmetlerini yürütmek üzere kanunla kurulan ve devletten ayrı bir varlığı bulunan tüzel kişiliktir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Belediye, ayrı bir kamu tüzel kişiliğidir." },
  { terim: "Kamu hizmeti", anlam: "Devlet ya da kamu tüzel kişileri tarafından toplumun ortak ihtiyacını karşılamak üzere yürütülen ve kamu hukukuna bağlı faaliyetlerdir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Eğitim ve sağlık hizmetleri birer kamu hizmetidir." },
  { terim: "Kamulaştırma", anlam: "Kamu yararı için ihtiyaç duyulan taşınmazın, bedeli peşin ödenerek özel mülkiyetten kamu mülkiyetine geçirilmesidir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Yol yapımı için tarla kamulaştırıldı." },
  { terim: "İmar planı", anlam: "Bir yerleşim yerinin gelecekteki düzenini, yapılaşma koşullarını ve arazi kullanımını gösteren planlardır. Uygulama zorunludur.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Belediye yeni imar planını askıya çıkardı." },
  { terim: "Ruhsat", anlam: "İdarenin, bazı faaliyetlerin kanuna uygun yürütülebilmesi için önceden verdiği izindir. Belli süre ve koşullara bağlanabilir.", ders: "Vatandaşlık", konu: "İdare Hukuku", ornek: "Bina yapımı için belediyeden ruhsat alındı." },
  { terim: "Vergi", anlam: "Devletin, kamu giderlerini karşılamak üzere kanunla ve karşılıksız olarak kişilerden aldığı ekonomik değerdir. Anayasaya göre herkes ödeme gücüne göre vergi öder.", ders: "Vatandaşlık", konu: "Mali Hukuk", ornek: "Vergi ancak kanunla konulur." },
  { terim: "Vergi mükellefi", anlam: "Üzerine vergi borcu düşen ve bu borcu ödemekle yükümlü olan gerçek ya da tüzel kişidir.", ders: "Vatandaşlık", konu: "Mali Hukuk", ornek: "Vergi mükellefi beyannamesini zamanında verdi." },
  { terim: "Bütçe", anlam: "Devletin gelecek yıla ait gelir ve giderlerinin tahmin edilerek izin verilmesini gösteren ve kanunla kabul edilen belgedir.", ders: "Vatandaşlık", konu: "Mali Hukuk", ornek: "Bütçe TBMM tarafından kanunla kabul edilir." },
  { terim: "Kamu Denetçiliği Kurumu", anlam: "İdarenin işlem ve eylemlerinden zarar gören kişilerin şikâyetlerini inceleyen ve öneri geliştiren bağımsız denetim kurumudur. Ombudsman olarak da bilinir.", ders: "Vatandaşlık", konu: "Denetim", ornek: "Kamu Denetçiliği Kurumu şikâyeti inceleyip rapor hazırladı." },
  { terim: "Türkiye Büyük Millet Meclisi", anlam: "Türk milleti adına egemenlik yetkisini kullanan, kanun yapan ve yürütmeyi denetleyen tek yasama organıdır. Milletvekilleri genel oyla seçilir.", ders: "Vatandaşlık", konu: "Yasama", ornek: "TBMM kanun teklifini görüşmeye açtı." },
  { terim: "Siyasi parti", anlam: "Programı doğrultusunda iktidar olmak ya da denetim görevi yapmak amacıyla kurulan ve süreklilik gösteren örgüttür.", ders: "Vatandaşlık", konu: "Siyasi Hayat", ornek: "Yeni bir siyasi parti kuruluş dilekçesini verdi." },
  { terim: "Milletvekili dokunulmazlığı", anlam: "Milletvekillerinin yasama faaliyetlerinden ötürü söz ve oylarından dolayı sorumlu tutulamamasıdır. Ayrıca yargı önünde özel güvence sağlar.", ders: "Vatandaşlık", konu: "Yasama", ornek: "Milletvekili dokunulmazlığı Meclis kararıyla kaldırılabilir." },
  { terim: "Nispi temsil", anlam: "Partilerin seçimde aldıkları oy oranına göre milletvekili kazanmasını esas alan seçim sistemidir. Temsilde adaleti güçlendirir.", ders: "Vatandaşlık", konu: "Seçim Hukuku", ornek: "Nispi temsil sistemi küçük partilerin de meclise girmesini sağlar." },
  { terim: "Seçim barajı", anlam: "Bir partinin mecliste temsil edilebilmesi için ülke genelinde alması gereken en az oy oranıdır.", ders: "Vatandaşlık", konu: "Seçim Hukuku", ornek: "Seçim barajını aşamayan parti meclise giremedi." },
  { terim: "Güven oylaması", anlam: "Hükûmetin ya da bir görevlinin göreve devam edip etmemesini belirlemek için meclisin yaptığı oylamadır.", ders: "Vatandaşlık", konu: "Yasama", ornek: "Hükûmet güven oylamasından geçti." },
  { terim: "Halk oylaması", anlam: "Anayasa değişikliği gibi önemli konularda halkın iradesinin doğrudan alındığı oylamadır. Referandum da denir.", ders: "Vatandaşlık", konu: "Seçim Hukuku", ornek: "Anayasa değişikliği halk oylamasına sunuldu." },
  { terim: "Soruşturma önergesi", anlam: "Meclisin belirli bir konuyu araştırmak için verdiği önerge türüdür. Kabul edilirse komisyon kurulur.", ders: "Vatandaşlık", konu: "Yasama", ornek: "Soruşturma önergesi Genel Kurulda kabul edildi." },
]);
